describe("extraUnsealPasswords", () => {
  const OLD = "old-password-old-password-old-password-1";
  const OLD2 = "old-password-old-password-old-password-2";
  const NEW = sessionConfig.password;
  const rotated: SessionConfig = { ...sessionConfig, password: NEW, extraUnsealPasswords: [OLD] };
  const legacyOptions = {
    ...sealDefaults,
    encryption: { ...sealDefaults.encryption, iterations: 1 },
    integrity: { ...sealDefaults.integrity, iterations: 1 },
  };
  const sealWith = (password: string, extra: Record<string, any> = {}, options = sealDefaults) =>
    seal({ id: "old", createdAt: Date.now(), data: { foo: "old" }, ...extra }, password, options);
  const cookieOf = (res: Response) =>
    decodeURIComponent(res.headers.getSetCookie()[0].match(/h3-test=([^;]+)/)![1]);

  beforeEach(() => {
    t.app.all("/rotated", async (event) => ({ session: await useSession(event, rotated) }));
    t.app.all("/rotated-nofallback", async (event) => ({
      session: await useSession(event, { ...rotated, legacySealFallback: false }),
    }));
    t.app.all("/rotated-two", async (event) => ({
      session: await useSession(event, { ...rotated, extraUnsealPasswords: [OLD, OLD2] }),
    }));
    t.app.all("/rotated-maxage", async (event) => ({
      session: await useSession(event, { ...rotated, maxAge: 60 }),
    }));
  });

  it("accepts extraUnsealPasswords and rejects an array password (types)", () => {
    const ok: SessionConfig = { password: NEW, extraUnsealPasswords: ["x"] };
    // @ts-expect-error password must stay a string
    const bad: SessionConfig = { password: ["x"] };
    expect([ok, bad]).toHaveLength(2);
  });

  it("seals only with password", async () => {
    const res = await t.fetch("/rotated");
    const sealed = cookieOf(res);
    expect(await unseal(sealed, NEW, sealDefaults)).toMatchObject({ data: {} });
    await expect(unseal(sealed, OLD, sealDefaults)).rejects.toThrow();
  });

  it("opens a session sealed with an extra password", async () => {
    const res = await t.fetch("/rotated", {
      headers: { Cookie: `h3-test=${await sealWith(OLD)}` },
    });
    expect(await res.json()).toMatchObject({ session: { id: "old", data: { foo: "old" } } });
  });

  it("tries extra passwords in order", async () => {
    const res = await t.fetch("/rotated-two", {
      headers: { Cookie: `h3-test=${await sealWith(OLD2)}` },
    });
    expect(await res.json()).toMatchObject({ session: { id: "old", data: { foo: "old" } } });
  });

  it("discards a session no password opens", async () => {
    const res = await t.fetch("/rotated", {
      headers: { Cookie: `h3-test=${await sealWith("unknown-".repeat(6))}` },
    });
    expect(res.status).toBe(200);
    const body = await res.json();
    expect(body.session.id).not.toBe("old");
    expect(body.session.data).toEqual({});
  });

  it("does not mask non-password errors (expired session)", async () => {
    const t0 = Date.parse("2030-01-01T00:00:00Z");
    vi.useFakeTimers({ toFake: ["Date"], now: t0 });
    try {
      const sealed = await sealWith(OLD, { createdAt: t0 - 120_000 });
      const res = await t.fetch("/rotated-maxage", { headers: { Cookie: `h3-test=${sealed}` } });
      const body = await res.json();
      expect(body.session.id).not.toBe("old");
      expect(body.session.data).toEqual({});
    } finally {
      vi.useRealTimers();
    }
  });

  it("reseals cookie sessions with password only", async () => {
    const res = await t.fetch("/rotated", {
      headers: { Cookie: `h3-test=${await sealWith(OLD)}` },
    });
    expect(res.headers.getSetCookie()).toHaveLength(1);
    const resealed = cookieOf(res);
    expect(await unseal(resealed, NEW, sealDefaults)).toMatchObject({
      id: "old",
      data: { foo: "old" },
    });
    await expect(unseal(resealed, OLD, sealDefaults)).rejects.toThrow();

    const res2 = await t.fetch("/rotated", { headers: { Cookie: `h3-test=${resealed}` } });
    expect(await res2.json()).toMatchObject({ session: { id: "old" } });
    expect(res2.headers.getSetCookie()).toHaveLength(0);
  });

  it("does not reseal sessions read from the session header", async () => {
    const res = await t.fetch("/rotated", {
      headers: { "x-h3-test-session": await sealWith(OLD) },
    });
    expect(await res.json()).toMatchObject({ session: { id: "old", data: { foo: "old" } } });
    expect(res.headers.getSetCookie()).toHaveLength(0);
  });

  it("combines legacy iterations with extra passwords", async () => {
    const sealed = await sealWith(OLD, {}, legacyOptions);
    const res = await t.fetch("/rotated", { headers: { Cookie: `h3-test=${sealed}` } });
    expect(await res.json()).toMatchObject({ session: { id: "old", data: { foo: "old" } } });
    expect(await unseal(cookieOf(res), NEW, sealDefaults)).toMatchObject({ id: "old" });

    const strict = await t.fetch("/rotated-nofallback", {
      headers: { Cookie: `h3-test=${sealed}` },
    });
    expect((await strict.json()).session.id).not.toBe("old");
  });

  it("keeps the unseal attempt count without extra passwords", async () => {
    const deriveBits = vi.spyOn(crypto.subtle, "deriveBits");
    const countFor = async (extra: string[] | undefined, path: string) => {
      t.app.get(path, async (event) => {
        await getSession(event, {
          ...sessionConfig,
          ...(extra === undefined ? {} : { extraUnsealPasswords: extra }),
        });
        return "ok";
      });
      deriveBits.mockClear();
      await t.fetch(path, { headers: { Cookie: `h3-test=${await sealWith("unknown-".repeat(6))}` } });
      return deriveBits.mock.calls.length;
    };
    const base = await countFor(undefined, "/count-none");
    expect(base).toBeGreaterThan(0);
    expect(await countFor([], "/count-empty")).toBe(base);
    deriveBits.mockRestore();
  });
});

